-- Templates that other rows point at but that did not exist (data from the LoA world DB). Safe to run twice.

-- Isle of Thunder: Zandalari Beastcaller riders (vehicle accessories of 69411, 69772), Mogu Warrior Spirit (accessory of 69574), Spirit Mask (kill credit of 69475, 69538)
DELETE FROM `creature_template` WHERE `entry` IN (69412,69476,69573,69780);

-- Spell focus objects summoned by the action list 6237700 (Gardener Fran watering her plants)
DELETE FROM `gameobject_template` WHERE `entry` IN (444000,444001,444002,444003,444004,444005,444006);

-- Model data of the Spirit Mask (the other three models are present)
